Contract SearchBook::searchBookByBarCode(barcode:String): Set(Book) {
          definition:
          obs:Set(BookCopy) = BookCopy.allInstance()->select(o | o.Barcode = barcode), result:Set(Book) = Set{}

            precondition:
          obs->notEmpty()

            postcondition:
          result = obs->collect(o | o.BookBelongs) and result->forAll(b | b.Copys->includes(obs->any(o | o.BookBelongs = b)))

        }
